60	        org.junit.jupiter.api.Assertions.assertEquals("PLANNED", diveRepository.get("DIVE-PF").status());
61	        org.junit.jupiter.api.Assertions.assertEquals(1,
62	                eventRepository.countByType("DIVE-PF", "PLAN_FROZEN"));
