 * @param surfacedAt      已确认出水时刻（UTC）；为空取服务时钟
 */
public record ControlledSurfaceRequest(
        @NotBlank String requestId,
        @NotBlank String diveRequestId,
        @NotNull @PositiveOrZero Integer expectedVersion,
        int bottomMin,
        Instant surfacedAt) {
}

